  const shadow=[{x:b.min.x-30,y:-2,z:b.min.z-30},{x:b.max.x+80,y:-2,z:b.min.z-30},{x:b.max.x+80,y:-2,z:b.max.z+70},{x:b.min.x-30,y:-2,z:b.max.z+70}].map(p=>this.projectPoint(p));if(shadow.every(p=>p.z<1)){c.save();c.shadowColor='#6470502a';c.shadowBlur=25;this.trace(shadow);c.fillStyle='#75875c12';c.fill();c.restore();}
  const faces=[],indices=[[1,5,7,3],[4,0,2,6],[0,1,3,2],[5,4,6,7],[2,3,7,6],[0,4,5,1]],light=new THREE.Vector3(-.4,.8,.65).normalize();
  for(const p of this.project.pieces){let verts=corners(p).map(v=>new THREE.Vector3(v.x,v.y,v.z));if(this.exploded&&!this.project.roomView){const center=new THREE.Vector3(p.x+p.w/2,p.y+p.h/2,p.z+p.d/2),dir=center.sub(middle);if(dir.length()<1)dir.set(0,1,0);dir.normalize().multiplyScalar(Math.max(this.project.w,this.project.h)*.14);verts=verts.map(v=>v.add(dir));}for(const ids of indices){const vs=ids.map(i=>verts[i]),normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize(),center=vs.reduce((a,v)=>a.add(v),new THREE.Vector3()).multiplyScalar(.25);if(normal.dot(this.camera.position.clone().sub(center))<=0)continue;const points=vs.map(v=>this.projectPoint(v));if(points.some(p=>p.z>1||p.z< -1))continue;const depth=center.clone().applyMatrix4(this.camera.matrixWorldInverse).z;faces.push({id:p.id,points,depth,material:p.material,color:p.color,environment:p.environment,wall:p.wall,shade:.86+normal.dot(light)*.16,selected:p.id===this.selected});}}
