  for(const f of faces){this.trace(f.points);const xs=f.points.map(p=>p.x),ys=f.points.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const gradient=c.createLinearGradient(minX,minY,maxX||1,maxY||1),base=f.color||MATERIALS[f.material].color;gradient.addColorStop(0,this.color(base,f.shade*1.035));gradient.addColorStop(1,this.color(base,f.shade*.985));c.fillStyle=f.environment&&f.id.startsWith('@wall')?this.color(base,f.shade):gradient;c.fill();c.lineJoin='round';c.lineWidth=f.selected?1.35:.7;c.strokeStyle=f.selected?'#5c7d3e':this.color(base,.72);if(!f.id.startsWith('@wall'))c.stroke();if(!f.environment&&['oak','walnut'].includes(f.material)&&maxX-minX>8&&maxY-minY>8){c.save();this.trace(f.points);c.clip();c.strokeStyle='#896e3f0b';c.lineWidth=.5;for(let i=0;i<14;i++){const t=(i+.5)/14;c.beginPath();c.moveTo(f.points[0].x*(1-t)+f.points[1].x*t,f.points[0].y*(1-t)+f.points[1].y*t);c.lineTo(f.points[3].x*(1-t)+f.points[2].x*t,f.points[3].y*(1-t)+f.points[2].y*t);c.stroke();}c.restore();}}
  if(this.showDimensions&&this.project.pieces.length){const a=b.min,z=b.max,off=ext*.10,n=v=>formatMeasure(v,this.project.unit||'mm');this.dimension({x:a.x,y:a.y-off,z:z.z+off},{x:z.x,y:a.y-off,z:z.z+off},n(z.x-a.x));this.dimension({x:a.x-off,y:a.y,z:z.z+off},{x:a.x-off,y:z.y,z:z.z+off},n(z.y-a.y));this.dimension({x:z.x+off,y:a.y-off,z:a.z},{x:z.x+off,y:a.y-off,z:z.z},n(z.z-a.z));}
